/// Practice question bank. Add new questions at the END only,
/// because saved progress uses each question's position in this list.

class PQ {
  const PQ(this.subject, this.qAr, this.qEn, this.optsAr, this.optsEn, this.correct, this.exAr, this.exEn);

  /// Key from subjectCatalog in content.dart.
  final String subject;
  final String qAr;
  final String qEn;
  final List<String> optsAr;

  /// null = same options in both languages.
  final List<String>? optsEn;
  final int correct;
  final String exAr;
  final String exEn;

  List<String> options(bool arabic) => arabic ? optsAr : (optsEn ?? optsAr);
}

